                operation.cancel()
            if not lost_waiter.done():
                lost_waiter.cancel()
            await asyncio.gather(operation, lost_waiter, return_exceptions=True)

    def _refresh_ownership(
        self,
        user_id: str,
        generation: int,
        ownership_lost: asyncio.Event,
    ) -> None:
